{
  "schema_version": "gtta.memo@1.0",
  "artifact_id": "memo-fertilizer-terminal-closure-triage",
  "title": "Strategic Risk Triage: Hypothetical Two-Month Major Fertilizer Export Terminal Closure",
  "question": "What are the strategic risks of a hypothetical two-month closure of a major fertilizer export terminal, and what must an agricultural-input buyer verify first?",
  "decision": "Establish operational triage priorities, audit supplier contractual obligations, and secure supply continuity without trading or procurement-price advice.",
  "audience": "Agricultural-input procurement directors and supply-chain risk leadership",
  "time_horizon": "60-day closure assumption plus 60-day operational recovery cycle",
  "mode": "A",
  "evidence_mode": "reasoning-only",
  "confidence": "Low",
  "bottom_line": {
    "claim_ids": [
      "CLM-001",
      "CLM-002",
      "CLM-003",
      "CLM-006"
    ],
    "text": "A hypothetical two-month closure of a major fertilizer export terminal threatens agricultural-input buyers primarily through irreversible delivery delays against rigid biological planting windows, compounded by probable supplier force majeure declarations. The buyer's immediate priority is not commercial price renegotiation or speculative hedging, but operational triage: first, verify contractual delivery terms and force majeure substitution obligations; second, calculate the hard run-out date of regional pipeline inventory against regional crop-application deadlines; and third, assess off-take throughput limits at alternative discharge corridors."
  },
  "sections": {
    "main_risks": {
      "claim_ids": [
        "CLM-002",
        "CLM-003",
        "CLM-004",
        "CLM-005",
        "CLM-008"
      ],
      "text": "The primary operational risks include: (1) Inflexible Application Windows [Risk Severity: High, Decision Relevance: High] — unlike industrial commodities, late fertilizer application causes irreversible agronomic yield loss, making delayed arrival functionally equivalent to non-delivery; (2) Contractual Force Majeure & Allocation Rationing [Risk Severity: High, Decision Relevance: High] — upstream producers impacted by the terminal outage will likely invoke force majeure or pro-rata allocation clauses, leaving the buyer with reduced volumes and no unilateral compensation; (3) Secondary Logistics Chokepoints [Risk Severity: Moderate, Decision Relevance: High] — diverting bulk dry or liquid volumes to adjacent maritime ports or domestic rail heads rapidly causes berth congestion, equipment shortages, and extended dwell times; and (4) Contract Frustration Risk [Risk Severity: High, Decision Relevance: Moderate] — extended disruption beyond 60 days risks permanent order cancellation by suppliers unable to secure alternative export permits or vessels."
    },
    "what_to_watch": {
      "claim_ids": [
        "CLM-005",
        "CLM-006",
        "CLM-007"
      ],
      "text": "The buyer must prioritize verifying non-commercial operational facts before making commitment shifts: (1) Contractual Terms and Substitution Rights — inspect existing agreements for Incoterms title-transfer points, specific port-of-loading definitions, and supplier obligations to fulfill from alternate berths; (2) Regional Inventory Run-Out Dates — audit intermediate storage levels to establish the exact calendar date when lack of inbound supply halts distribution to growers; and (3) Alternate Corridor Congestion — track railcar availability, secondary port vessel queues, and terminal draft limits before committing to rerouted freight corridors."
    }
  },
  "claims": [
    {
      "claim_id": "CLM-001",
      "kind": "assumption",
      "provenance": "analyst-judgment",
      "text": "A major export terminal handling regional bulk fertilizer shipments is assumed to experience complete operational closure for an uninterrupted duration of 60 days.",
      "basis_claim_ids": []
    },
    {
      "claim_id": "CLM-002",
      "kind": "assessment",
      "provenance": "inference",
      "text": "A 60-day terminal closure disrupts scheduled maritime vessel nominations and creates immediate supply-chain bullwhip delays exceeding the physical shutdown duration due to port recommissioning and fleet rescheduling.",
      "basis_claim_ids": [
        "CLM-001"
      ]
    },
    {
      "claim_id": "CLM-003",
      "kind": "assessment",
      "provenance": "analyst-judgment",
      "text": "The critical strategic risk for an agricultural-input buyer is delivery timing relative to inflexible biological planting application windows, where late fertilizer delivery creates irreversible yield loss regardless of eventual product arrival.",
      "basis_claim_ids": [
        "CLM-002"
      ]
    },
    {
      "claim_id": "CLM-004",
      "kind": "assessment",
      "provenance": "analyst-judgment",
      "text": "Suppliers impacted by terminal outages will likely claim force majeure or invoke pro-rata volume allocation clauses to relieve delivery obligations rather than absorb secondary rerouting costs.",
      "basis_claim_ids": [
        "CLM-001"
      ]
    },
    {
      "claim_id": "CLM-005",
      "kind": "assessment",
      "provenance": "inference",
      "text": "Attempting to reroute cargo through neighboring terminals will saturate regional bulk logistics and inland discharge corridors, generating secondary demurrage and berth congestion.",
      "basis_claim_ids": [
        "CLM-001"
      ]
    },
    {
      "claim_id": "CLM-006",
      "kind": "assessment",
      "provenance": "analyst-judgment",
      "text": "Auditing legal contract terms and supplier alternate-origin clauses provides the earliest determination of whether the buyer must arrange substitute logistics or accept volume reductions.",
      "basis_claim_ids": [
        "CLM-004"
      ]
    },
    {
      "claim_id": "CLM-007",
      "kind": "unknown",
      "provenance": "analyst-judgment",
      "text": "The exact buffer volume of intermediate domestic warehouse inventory available to absorb the two-month supply gap remains unverified in the absence of buyer inventory records.",
      "basis_claim_ids": []
    },
    {
      "claim_id": "CLM-008",
      "kind": "scenario",
      "provenance": "inference",
      "text": "In the event of an extended disruption beyond 60 days, suppliers may cancel pending orders entirely under frustration-of-contract doctrines, halting downstream blending operations.",
      "basis_claim_ids": [
        "CLM-001",
        "CLM-004"
      ]
    }
  ],
  "options": [
    {
      "option_id": "OPT-01",
      "title": "Legal Contract & Force Majeure Scope Audit",
      "benefit": "Establishes whether the supplier has the legal right to suspend deliveries or is obligated to fulfill orders from alternative export berths or substitute origins.",
      "downside": "May create adversarial tension with key suppliers if legal notices are issued before operational realities are verified.",
      "conditions": "Execute immediately as the primary triage step prior to any operational shifts or alternative commitments.",
      "basis_claim_ids": [
        "CLM-004",
        "CLM-006"
      ]
    },
    {
      "option_id": "OPT-02",
      "title": "Agronomic Application Window & Buffer Stock Run-Out Calculation",
      "benefit": "Identifies the exact operational drop-dead date when fertilizer must be in local storage, delineating critically exposed product lines from deferrable volumes.",
      "downside": "Requires reconciling internal inventory and customer application schedules across distributed regional distribution centers.",
      "conditions": "Execute concurrently with contract audits across all primary nutrient segments (nitrogen, phosphate, potash).",
      "basis_claim_ids": [
        "CLM-003",
        "CLM-007"
      ]
    },
    {
      "option_id": "OPT-03",
      "title": "Secondary Corridor & Transshipment Feasibility Review",
      "benefit": "Maps physical throughput limits, rail discharge capacities, and truck fleet availability for rerouted bulk shipments before secondary corridors become congested.",
      "downside": "Requires non-binding coordination with logistics operators without committing capital prematurely.",
      "conditions": "Deploy once contract audits clarify whether buyer or seller holds freight routing and demurrage responsibility.",
      "basis_claim_ids": [
        "CLM-002",
        "CLM-005"
      ]
    }
  ],
  "indicators": [
    {
      "indicator_id": "IND-01",
      "indicator": "Formal supplier force majeure or delivery rescheduling notifications",
      "trigger": "Receipt of formal written notice citing terminal impossibility or proposing delivery deferral past 14 days",
      "posture_change": "Request proof of alternate loading port exhaustion and formally trigger contractual substitution provisions",
      "basis_claim_ids": [
        "CLM-004"
      ]
    },
    {
      "indicator_id": "IND-02",
      "indicator": "Alternative regional port vessel queues and berth dwell times",
      "trigger": "Average vessel waiting time at secondary regional bulk terminals exceeds 7 days over normal operating baseline",
      "posture_change": "Pre-screen domestic inland rail and truck haulage corridors to bypass congested coastal discharge points",
      "basis_claim_ids": [
        "CLM-005"
      ]
    },
    {
      "indicator_id": "IND-03",
      "indicator": "Regional buffer stock depletion velocity vs crop planting schedule",
      "trigger": "Depot inventory falls below 30 days of projected planting demand with no confirmed vessel laycan or bill of lading",
      "posture_change": "Implement non-price internal delivery rationing to protect high-priority agricultural customer commitments",
      "basis_claim_ids": [
        "CLM-003",
        "CLM-007"
      ]
    }
  ],
  "key_unknowns": [
    "Specific product mix throughput (dry bulk urea/DAP vs refrigerated liquid ammonia) handled by the closed terminal.",
    "Exact contractual Incoterms and port substitution clauses in active procurement agreements.",
    "Current physical buffer stock volumes held at intermediate destination warehouses and blending hubs.",
    "Spare capacity and draft limits of alternative maritime terminals and domestic rail discharge corridors."
  ],
  "limitations": [
    "Evidence limit: this memo was produced without live source retrieval or access to proprietary data. Claims should be verified against primary sources before irreversible decisions.",
    "Terminal outage is evaluated strictly as a hypothetical planning assumption, not a confirmed operational event.",
    "Commodity trading, price hedging, and spot procurement tactics are explicitly excluded from scope."
  ],
  "change_conditions": [
    "Official operational report confirming the terminal closure will terminate within 30 days rather than 60 days.",
    "Confirmation that primary suppliers have successfully shifted export laycans to operational alternate terminals.",
    "Legal determination that applicable sales contracts exclude terminal outages from force majeure protections.",
    "Host government declaration of export controls or maritime movement restrictions affecting fertilizer trade."
  ]
}
